    return 1

def stable(w:mutbuf, a:u64, b:u64) -> u64:
    if get(w, a) != get(w, b) or get(w, a + 8) != get(w, b + 8):
        return 0
    if get(w, a + 16) != get(w, b + 16) or get(w, a + 24) != get(w, b + 24):
        return 0
