# Linux UAPI values also cover Python builds that omit the fcntl names.
_EXECUTABLE_SEALS = (getattr(fcntl,'F_SEAL_WRITE',0x0008)
    |getattr(fcntl,'F_SEAL_GROW',0x0004)|getattr(fcntl,'F_SEAL_SHRINK',0x0002)
